export function paintCliffOverlay(ctx, tile, neighbors, sx, sy, size, sun) {
  var myLevel = cliffLevel(tile.climate.elevation);
  var nLevel = cliffLevel(neighbors.north);
  var eLevel = cliffLevel(neighbors.east);
  var sLevel = cliffLevel(neighbors.south);
  var seLevel = cliffLevel(neighbors.southeast);
  var neLevel = cliffLevel(neighbors.northeast);
  var swLevel = cliffLevel(neighbors.southwest);

  // Corner mask: NW = tile, NE = E-neighbor, SW = S-neighbor, SE = SE-neighbor
  // Bits set when corresponding cell is on a HIGHER cliff level
  var cliffMask = 0;
  if (myLevel < nLevel) cliffMask |= 8;   // NW corner (tile compared to N — actually NW is always tile)
  // NW: compare tile level to N neighbor's level — if N is higher, cliff at NW
  if (myLevel >= nLevel) { /* tile is not lower than N */ }
  // Actually, corners: NW=tile, NE=E, SW=S, SE=SE. Cliff at corner when that neighbor is higher.
  if (myLevel < eLevel) cliffMask |= 4;    // NE corner
  if (myLevel < sLevel) cliffMask |= 2;    // SW corner
  if (myLevel < seLevel) cliffMask |= 1;   // SE corner

  if (cliffMask === 0) return;

  var alpha = Math.min(0.55, (1 - sun.height) * 0.40 + 0.20);
  ctx.fillStyle = 'rgba(10,8,12,' + alpha.toFixed(2) + ')';

  // Draw cliff shadow strips based on which corners have higher neighbors
  var s = size;

  // SE corner cliff (SE neighbor higher)
  if (cliffMask & 1) {
    ctx.fillRect(sx + s * 0.5, sy + s * 0.5, s * 0.5, s * 0.5);
  }
  // SW corner cliff (S neighbor higher)
  if (cliffMask & 2) {
    ctx.fillRect(sx, sy + s * 0.5, s * 0.5, s * 0.5);
  }
  // NE corner cliff (E neighbor higher)
  if (cliffMask & 4) {
    ctx.fillRect(sx + s * 0.5, sy, s * 0.5, s * 0.5);
  }
  // NW corner cliff (N neighbor higher — also our own NW)
  // NW uses N neighbor comparison; if N level > my level, shade top-left
  if (myLevel < nLevel) {
    ctx.fillRect(sx, sy, s * 0.5, s * 0.5);
  }
}

