// Draw cliff face Wang tiles on the high side of an elevation step.
// Overlay drawn on the HIGHER tile where it drops to a lower neighbor.
// Corner convention: self=NW, E=NE, S=SW, SE=SE (same as biome transitions).
// "from" = lower elevation, so bits = 1 where corner drops.
export function paintCliffOverlay(ctx, tile, sx, sy, size, sun) {
  var myEl = tile.climate.elevation;
  var myLevel = cliffLevel(myEl);

  // Only draw on the HIGHER tile — check if any neighbor is lower
  var cornerMask = 0;
  // NW = self — tile is always same level as itself, so NW never flags here
  if (myLevel > cliffLevel(tile._elE  || myEl)) cornerMask |= 4;  // NE drops
  if (myLevel > cliffLevel(tile._elS  || myEl)) cornerMask |= 2;  // SW drops
  if (myLevel > cliffLevel(tile._elSE || myEl)) cornerMask |= 1;  // SE drops

  if (cornerMask === 0) return;

  var wangIndex = CLIFF_CORNER_TO_WANG[cornerMask];
  var cliffDir = BIOME_CLIFF[tile.biome] || 'cliff_overlay';
  var src = TRANSITIONS_BASE + cliffDir + '/wang/' + cliffDir + '__wang_' + wangIndex + WANG_SUFFIX;

  var img = wangImgCache[src];
  if (!img || !img.complete || !img.naturalWidth) return;
  ctx.drawImage(img, 0, 0, 32, 32, sx, sy, size, size);
}

